// HEAP ARRAY REPRESENTATION (1-indexed for cleaner arithmetic)
// Index:  1   2   3   4   5   6   7
// Value: [3,  5,  4,  8,  7,  6,  9]
// Tree:       3
//           /   \
//          5     4
//         / \   / \
//        8   7 6   9
// Min-heap: every parent <= both children ✓
// 3<=5 ✓  3<=4 ✓  5<=8 ✓  5<=7 ✓  4<=6 ✓  4<=9 ✓

class MinHeap {
    constructor() {
        this.heap = [null]; // index 0 unused for cleaner 1-indexed arithmetic
    }
    get size() { return this.heap.length - 1; }

    // INDEX ARITHMETIC (1-indexed)
    _parent(i) { return Math.floor(i / 2); }
    _left(i)   { return 2 * i; }
    _right(i)  { return 2 * i + 1; }

    // PEEK: read minimum — O(1)
    peek() { return this.size > 0 ? this.heap[1] : null; }

    // SWAP helper
    _swap(i, j) {
        [this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];
    }

    toArray() { return this.heap.slice(1); }
}

// VERIFY INDEX ARITHMETIC
const h = new MinHeap();
h.heap = [null, 3, 5, 4, 8, 7, 6, 9]; // manually set
console.log('Parent of index 4:', h._parent(4)); // 2 ✓ (5 is parent of 8)
console.log('Left of index 2:', h._left(2));     // 4 ✓ (8 is left child of 5)
console.log('Right of index 2:', h._right(2));   // 5 ✓ (7 is right child of 5)
console.log('Root (minimum):', h.peek());         // 3 ✓

