class MinHeap {
    constructor() { this.heap = [null]; }
    get size() { return this.heap.length - 1; }
    peek()     { return this.size > 0 ? this.heap[1] : null; }
    _parent(i) { return Math.floor(i / 2); }
    _left(i)   { return 2 * i; }
    _right(i)  { return 2 * i + 1; }
    _swap(i,j) { [this.heap[i],this.heap[j]]=[this.heap[j],this.heap[i]]; }

    // INSERT: append then sift-up — O(log n)
    insert(val) {
        this.heap.push(val);          // step 1: append (maintain completeness)
        this._siftUp(this.size);      // step 2: restore heap property
    }
    _siftUp(i) {
        while (i > 1 && this.heap[this._parent(i)] > this.heap[i]) {
            this._swap(i, this._parent(i));
            i = this._parent(i);
        }
    }

    // EXTRACT MIN: swap root with last, remove, sift-down — O(log n)
    extractMin() {
        if (this.size === 0) return null;
        if (this.size === 1) return this.heap.pop();
        const min = this.heap[1];     // save minimum
        this.heap[1] = this.heap.pop(); // move last to root
        this._siftDown(1);            // restore heap property
        return min;
    }
    _siftDown(i) {
        while (true) {
            let smallest = i;
            const l = this._left(i), r = this._right(i);
            if (l <= this.size && this.heap[l] < this.heap[smallest]) smallest = l;
            if (r <= this.size && this.heap[r] < this.heap[smallest]) smallest = r;
            if (smallest === i) break; // heap property restored
            this._swap(i, smallest);
            i = smallest;
        }
    }

    // HEAPIFY: build heap from array in O(n)
    static fromArray(arr) {
        const h = new MinHeap();
        h.heap = [null, ...arr];      // copy array into heap (1-indexed)
        // Sift-down all non-leaf nodes from bottom to top
        for (let i = Math.floor(h.size / 2); i >= 1; i--) {
            h._siftDown(i);
        }
        return h;
    }
}

