// KTH LARGEST — min-heap of size k: O(n log k) time, O(k) space
function findKthLargest(nums, k) {
    const heap = new MinHeap();
    for (const num of nums) {
        heap.insert(num);
        if (heap.size > k) heap.extractMin(); // remove smallest: keep k largest
    }
    return heap.peek(); // root = smallest of the k largest = kth largest
}

// TRACE on [3,2,1,5,6,4], k=2:
// insert 3: heap=[3]
// insert 2: heap=[2,3]
// insert 1: heap=[1,3,2] size=3>2 -> extract 1: heap=[2,3]
// insert 5: heap=[2,3,5] size=3>2 -> extract 2: heap=[3,5]
// insert 6: heap=[3,5,6] size=3>2 -> extract 3: heap=[5,6]
// insert 4: heap=[4,6,5] size=3>2 -> extract 4: heap=[5,6]
// peek() = 5 = 2nd largest ✓
console.log(findKthLargest([3,2,1,5,6,4], 2)); // 5
console.log(findKthLargest([3,2,3,1,2,4,5,5,6], 4)); // 4

// QUICKSELECT alternative: O(n) average, O(n^2) worst case
function findKthLargestQuickselect(nums, k) {
    const target = nums.length - k; // kth largest = (n-k)th smallest (0-indexed)
    function partition(lo, hi) {
        const pivotIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
        [nums[pivotIdx], nums[hi]] = [nums[hi], nums[pivotIdx]];
        const pivot = nums[hi];
        let i = lo - 1;
        for (let j = lo; j < hi; j++) {
            if (nums[j] <= pivot) { i++; [nums[i], nums[j]] = [nums[j], nums[i]]; }
        }
        [nums[i+1], nums[hi]] = [nums[hi], nums[i+1]];
        return i + 1;
    }
    let lo = 0, hi = nums.length - 1;
    while (lo < hi) {
        const p = partition(lo, hi);
        if (p === target) break;
        else if (p < target) lo = p + 1;
        else hi = p - 1;
    }
    return nums[target];
}

