function topKFrequent_heap(nums, k) {
    // Build frequency map
    const freq = new Map();
    for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);

    // Min-heap storing [frequency, element] pairs
    // We need a custom comparator: compare by frequency (first element of pair)
    // In JS without a built-in heap library, simulate with array + sort trick
    // or use our MinHeap with pair comparison
    const heap = []; // [frequency, element] pairs, maintained as min-heap by freq

    // Simple simulation: collect all pairs, sort by freq, take top k
    // (This is the O(n log n) approach for clarity; use proper heap for O(n log k))
    for (const [element, frequency] of freq) {
        heap.push([frequency, element]);
    }
    heap.sort((a, b) => b[0] - a[0]); // sort by frequency descending
    return heap.slice(0, k).map(pair => pair[1]);
}

// APPROACH 2: BUCKET SORT — O(n) optimal for this problem
function topKFrequent_bucket(nums, k) {
    const freq = new Map();
    for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);

    // Buckets indexed by frequency (0..nums.length)
    const buckets = new Array(nums.length + 1).fill(null).map(() => []);
    for (const [element, frequency] of freq) {
        buckets[frequency].push(element);
    }

    // Collect from highest frequency downward
    const result = [];
    for (let f = buckets.length - 1; f >= 1 && result.length < k; f--) {
        result.push(...buckets[f]);
    }
    return result.slice(0, k);
}

// APPROACH 3: PROPER MIN-HEAP OF SIZE K — O(n log k)
// Requires MinHeap with custom comparator for pairs
function topKFrequent_minheap(nums, k) {
    const freq = new Map();
    for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);

    // pairs sorted by frequency ascending (min-heap semantics)
    const pairs = [...freq.entries()].map(([el, fr]) => [fr, el]);
    // O(n log k): insert all, maintain size k
    // Using sort as proxy (proper implementation needs custom heap)
    pairs.sort((a, b) => a[0] - b[0]); // sort ascending by freq
    return pairs.slice(pairs.length - k).map(p => p[1]);
}

