function kClosest(points, k) {
    // Max-heap: store [squaredDist, point] pairs
    // Use array sorted descending (simulating max-heap with sorted array)
    // For production: implement MaxHeap with custom comparator
    const heap = []; // [squaredDist, point]

    const sqDist = ([x, y]) => x * x + y * y;

    for (const point of points) {
        const dist = sqDist(point);
        heap.push([dist, point]);
        // Keep only k closest: sort descending and trim if needed
