// MERGE K SORTED LISTS using min-heap — O(N log k)
function mergeKLists(lists) {
    const dummy = new ListNode(0);
    let curr = dummy;

    // Priority queue: [value, list_index, node]
    // Min-heap ordered by node value
    // Using array + sort simulation (production: proper MinHeap)
    const heap = [];

    // Initialise: add head of each non-empty list
    for (let i = 0; i < lists.length; i++) {
        if (lists[i]) heap.push([lists[i].val, i, lists[i]]);
    }
    heap.sort((a, b) => a[0] - b[0]); // sort ascending by value

    while (heap.length) {
        // Extract minimum
        const [val, idx, node] = heap.shift(); // O(1) with proper heap
        curr.next = node;
        curr = curr.next;

        // Push next node from same list
        if (node.next) {
            // Insert in sorted position (O(log k) with proper heap)
            const next = node.next;
            const entry = [next.val, idx, next];
            // Binary insert for simulation:
            let lo = 0, hi = heap.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (heap[mid][0] < entry[0]) lo = mid + 1;
                else hi = mid;
            }
            heap.splice(lo, 0, entry);
        }
    }
    return dummy.next;
}

