// TASK SCHEDULER — greedy with max-heap + cooldown queue
// O(t * log 26) where t = total task time (bounded by O(t))
function leastInterval(tasks, n) {
    // Count frequencies
    const freq = new Array(26).fill(0);
    for (const t of tasks) freq[t.charCodeAt(0) - 65]++;
    freq.sort((a, b) => b - a); // sort descending

    // Max-heap of current frequencies (only non-zero)
    // Simulate max-heap with sorted array
    let heap = freq.filter(f => f > 0).sort((a, b) => b - a);
    let time = 0;
    const queue = []; // [remaining_freq, available_at]

    while (heap.length || queue.length) {
        time++;
        // Re-add tasks whose cooldown has expired
        if (queue.length && queue[0][1] === time) {
            const [remFreq] = queue.shift();
            heap.push(remFreq);
            heap.sort((a, b) => b - a); // maintain max-heap order
        }
        // Execute most frequent available task
        if (heap.length) {
            const remFreq = heap.shift() - 1;
            if (remFreq > 0) queue.push([remFreq, time + n + 1]);
        }
        // else: CPU idle this time unit
    }
    return time;
}

// MATHEMATICAL FORMULA — O(1) after counting
function leastIntervalFormula(tasks, n) {
    const freq = new Array(26).fill(0);
    for (const t of tasks) freq[t.charCodeAt(0) - 65]++;
    const maxFreq = Math.max(...freq);
    const countMaxFreq = freq.filter(f => f === maxFreq).length;
    // Formula: arrange maxFreq-1 complete cycles, each of length n+1,
    // plus a final partial cycle with all tasks at max frequency
    const formulaResult = (maxFreq - 1) * (n + 1) + countMaxFreq;
    return Math.max(tasks.length, formulaResult);
    // Math.max because if tasks.length > formula, no idle time needed
}

