class MedianFinder {
    constructor() {
        // maxHeap: lower half — peek() gives the largest of the smaller values
        // minHeap: upper half — peek() gives the smallest of the larger values
        this.maxHeap = new MaxHeap(); // needs MaxHeap implementation
        this.minHeap = new MinHeap();
    }

    addNum(num) {
        // Step 1: insert into correct heap
        if (this.maxHeap.size === 0 || num <= this.maxHeap.peek()) {
            this.maxHeap.insert(num); // goes in lower half
        } else {
            this.minHeap.insert(num); // goes in upper half
        }

        // Step 2: rebalance so maxHeap is at most 1 larger
        if (this.maxHeap.size > this.minHeap.size + 1) {
            // maxHeap has 2+ more elements: move its max to minHeap
            this.minHeap.insert(this.maxHeap.extractMax());
        } else if (this.minHeap.size > this.maxHeap.size) {
            // minHeap is larger: move its min to maxHeap
            this.maxHeap.insert(this.minHeap.extractMin());
        }
    }

    findMedian() {
        if (this.maxHeap.size > this.minHeap.size) {
            return this.maxHeap.peek(); // odd total: middle element
        }
        // Even total: average of the two middle elements
        return (this.maxHeap.peek() + this.minHeap.peek()) / 2;
    }
}

